','d969897c-b5c2-48c8-8fe0-680585dc0a06','d9cd5119-c960-49b1-bf64-34ca580dbbd2','db162b18-d2a9-482c-8b51-4dcc365063fb','db180f54-8f68-4d74-b949-300cf6f1a1c4','db5ba838-0adc-476a-ba76-fea6aa10887a','dbb8d019-ed8c-4142-a4f6-a04bb7757ad4','df7ef652-e3a9-41d5-ac4d-05cde19f7a8e','e0541357-c405-4d46-becc-bbca5ea825a8','e0b68963-5c03-43e9-a212-08d1f01008a1','e0d55b2d-144d-43fc-b45a-ce2083f7ae61','e20b93df-23a5-4f5b-a47a-18980c09db2c','e3a895ef-de23-431c-bd79-584b5e16550b','e4ca8f01-7d6d-44ce-b6f7-bed752492ed5','e8b69a05-03b7-413d-ae34-3e8df7bc2899','e8c528cf-d252-433e-98ea-0296b0a695c2','e9241f38-495c-4e70-9a5f-b9b5c7d804f8','ea65295a-c5d0-49e1-a390-da90f8b70976','eaaab20b-0cb9-443a-baf2-1bed22a135a2','eac62c71-83f1-4d2d-9c7a-aaf3cdedeaa6','ebdf0ae9-13b6-40ea-a209-231155511883','ee819c4a-62c4-48fc-adb8-0aa218591f8f','efea82ad-f4d7-43d6-875f-0de27681ca8e','f135a6a9-375b-4f77-a40e-efd0a2603ff3','f1fca6ba-dc60-4134-a773-354b064c6854','f22bf9c8-9e15-4a86-94b8-d8dfd8f178c6','f247517e-e08a-475c-909c-3ccc1aa4fed3','f385288e-6be5-4b6b-9a23-23612295360c','f719cdbb-754d-4ddc-b65c-5f55784dedb7','f954648d-9eaa-41fd-882b-68b1ecd3e32e','f9f0b422-c56c-489d-90aa-2ae1b52fedaf','fab99872-6681-4c64-9920-2031759398b0','fcd0c3e1-76f5-4c64-ba2c-31221c0e1ff1','fd218aef-bbe8-4d5d-a6d7-817ab94aded7','fd72a620-a85f-4671-96b2-cbc84e11fcdc','fdc61e25-e426-4206-98ee-c707d33a20ca','fea008ee-5b22-4bb8-9dea-008279e1b6df','fff18ef0-e7cb-47ad-a412-e4d92a6108b5']::uuid[];
  v_count integer;
  v_amount numeric;
  v_id uuid;
  v_value numeric;
  v_r jsonb;
  v_n integer:=0;
  v_sum numeric:=0;
  v_ids uuid[]:=ARRAY[]::uuid[];
BEGIN
  IF to_regprocedure('public.fn_ca_pay_closed_target_ticket_in_cash(uuid,text)') IS NULL THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_DOOR_MISSING: apply 20261012054804 first';
  END IF;
  SELECT count(*), COALESCE(sum(tk.value),0) INTO v_count,v_amount
    FROM public.tournament_tickets tk WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-01 00:00:00+00' AND tk.created_at<'2026-09-12 19:00:00+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id);
  IF v_count<>190 OR v_amount<>14660.00 THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_PREIMAGE_CHANGED: part 1 has % tickets worth %',v_count,v_amount;
  END IF;
  FOR v_id,v_value IN
    SELECT tk.id,tk.value FROM public.tournament_tickets tk
     WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-01 00:00:00+00' AND tk.created_at<'2026-09-12 19:00:00+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id)
     ORDER BY tk.created_at,tk.id
  LOOP
    v_r:=public.fn_ca_pay_closed_target_ticket_in_cash(v_id,'stranded_ticket_settlement_20261012');
    IF COALESCE((v_r->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE((v_r->>'replayed')::boolean,false)
       OR (v_r->>'amount')::numeric IS DISTINCT FROM v_value THEN
      RAISE EXCEPTION 'STRANDED_TICKET_CASH_REFUSED: %',v_r;
    END IF;
    v_n:=v_n+1;
    v_sum:=round(v_sum+v_value,2);
    v_ids:=v_ids||v_id;
  END LOOP;
  IF v_n<>190 OR v_sum<>14660.00 THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_RESULT_CHANGED: paid % tickets worth %',v_n,v_sum;
  END IF;
  IF (SELECT count(*) FROM public.tournament_tickets tk
       WHERE tk.id=ANY(v_ids) AND tk.status='redeemed'
         AND tk.redeemed_at=transaction_timestamp())<>v_n
     OR (SELECT COALESCE(sum(l.amount),0)
           FROM public.chip_ledger_idem i JOIN public.chip_ledger l ON l.id=i.leg_id
          WHERE i.idempotency_key IN (
            SELECT 'ticket:'||x::text||':closed-target-cash' FROM unnest(v_ids) x)
            AND l.from_type='escrow' AND l.to_type='player_wallet'
            AND l.category='ticket_redeem')<>v_sum
     OR EXISTS (SELECT 1 FROM public.tournament_tickets tk WHERE tk.id=ANY(v_witness) AND tk.status='issued' AND tk.redemption_mode='tournament_entry_only' AND tk.source_satellite_award_place IS NOT NULL AND tk.source_refund_entitlement_id IS NULL AND tk.created_at>='2026-09-01 00:00:00+00' AND tk.created_at<'2026-09-12 19:00:00+00' AND public.fn_ca_satellite_ticket_target_is_closed(tk.source_tournament_id)) THEN
    RAISE EXCEPTION 'STRANDED_TICKET_CASH_RESULT_CHANGED: receipts disagree for % tickets worth %',v_n,v_sum;
  END IF;
  RAISE NOTICE 'stranded satellite tickets paid in cash, part 1: % tickets worth %',v_n,v_sum;
END
$settle$;
COMMIT;
